import React from 'react';

import clsx from 'clsx';

import DayInfoWidget from '@apps/Hiking/one/components/DayInfoWidget';
import RecipeCookingInfo from '@apps/Recipes/components/RecipeCookingInfo';
import BGU from '@components/BGU/index';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader/index';
import { digitsDivision } from '@helpers/formatHelper';
import { round } from '@helpers/mathHelper';
import { err } from '@helpers/notificationHelper';
import PohAva from '@ui-kit/Ava';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import Breadcrumb from '@ui-kit/Breadcrumb/index';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row/index';

import style from './style.module.less';
import { includeActInfo } from '../../../@mappers/hikingMenu.mapper';
import { getHikingDataAsync } from '../../../@services/hiking.service';
import { getHikingDuty } from '../../../@services/hikingDuty.service';
import {
  getFoodAsync,
  getHikingMenuActs,
  getHikingMenuProductsAsync,
} from '../../../@services/hikingMenu.service';
import { IHikingDuty } from '../../../@types/hiking.baseTypes';
import { IHikingData } from '../../../@types/hiking.types';
import {
  IHikingMenuActsByDays,
  IHikingMenuExtendedProduct,
  IHikingMenuFoodWithAct,
} from '../../../@types/hikingMenu.types';
import { getShortName } from '../HikingMenu/helper';

interface IHikingMenuPrintProps {
  id_hiking: number;
}

interface HikingMenuPrintProps {
  id_hiking: number;
}

const HikingMenuPrint: React.FC<IHikingMenuPrintProps> = ({ id_hiking }: HikingMenuPrintProps) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);

  const [daysActs, setDaysActs] = React.useState<IHikingMenuActsByDays[]>([]);
  const [food, setFood] = React.useState<IHikingMenuFoodWithAct[]>([]);
  const [products, setProducts] = React.useState<IHikingMenuExtendedProduct[]>([]);
  const [duty, setDuty] = React.useState<IHikingDuty[]>([]);

  React.useEffect(() => {
    const init = async () => {
      const hd = await getHikingDataAsync(id_hiking);
      setHikingData(hd);

      const hda = await getHikingMenuActs(id_hiking);
      setDaysActs(hda);

      const hf = await getFoodAsync({ id_hiking });
      const hfWithActs = hf.map(includeActInfo(hda));
      setFood(hfWithActs);

      const pdts = await getHikingMenuProductsAsync(id_hiking);
      setProducts(pdts);

      const dts = await getHikingDuty(id_hiking);
      setDuty(dts);
    };

    init().catch(err);
  }, [id_hiking]);

  if (hikingData == null) {
    return <PageLoader />;
  }

  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name },
          { href: `/hiking/${id_hiking}/equip`, text: 'Меню похода', active: true },
        ]}
      />
      <PageHeader className="d-print-none" title={`Меню похода ${hikingData.name}`}></PageHeader>
      {daysActs?.length > 0 &&
        daysActs.map((day, ind) => {
          const todayDuty = duty.filter(
            (d) => d.date.toLocaleDateString() === day.date.toLocaleDateString(),
          );

          return (
            <div key={day.date.toString()} className="mt-3">
              <section>
                {day.acts.map((act) => {
                  const actFood = food.filter(
                    (x) =>
                      x.date.toLocaleDateString() === day.date.toLocaleDateString() &&
                      x.id_act === +act.id,
                  );
                  const factDayAct = actFood.reduce(
                    (acc, f) => ({
                      energy: acc.energy + f.energy * f.correction,
                      amount: acc.amount + f.amount * f.correction,
                      proteins: acc.proteins + f.proteins * f.correction,
                      fats: acc.fats + f.fats * f.correction,
                      carbs: acc.carbs + f.carbs * f.correction,
                    }),
                    { energy: 0, amount: 0, proteins: 0, fats: 0, carbs: 0 },
                  );

                  const date = day.date;
                  const uset = new Set();

                  const firstAssigneeUser = actFood.find((foo) => foo?.assigneeUser);

                  return (
                    <PohRow
                      key={`${day.date.toString()}${act.id}`}
                      className={clsx('border-bottom mt-4 mb-4 pb-4', style.breakPage)}
                    >
                      <PohCol sm={12}>
                        <header
                          className={clsx(
                            'd-flex align-items-center justify-content-between',
                            style.noBreak,
                          )}
                        >
                          <div className="d-flex align-items-center">
                            <h5 className="my-2">
                              <PohBadge variant={BadgeVariant.Success} className="me-1">
                                Д-{ind + 1}
                              </PohBadge>
                              <PohBadge className="me-2">
                                <b>{act.name}</b>
                              </PohBadge>
                            </h5>
                            <DayInfoWidget date={date} className="me-3" />
                          </div>
                          <div>
                            <div className="d-flex align-items-center mx-4">
                              {firstAssigneeUser?.assigneeUser && (
                                <div className="d-flex border-end me-3 pe-3">
                                  <small className={clsx('text-muted', style.hCap)}>ОТВ</small>
                                  <small className="d-flex align-items-center" style={{ gap: 5 }}>
                                    <PohAva
                                      width={20}
                                      src={firstAssigneeUser?.assigneeUser.photo}
                                      alt={firstAssigneeUser?.assigneeUser.name}
                                    />
                                    <div style={{ lineHeight: '0.85em' }}>
                                      <small className="d-block mt-1">
                                        {firstAssigneeUser?.assigneeUser.name?.split(/\s/)[0]}
                                      </small>
                                      <small className="d-block text-muted">
                                        {firstAssigneeUser?.assigneeUser.name?.split(/\s/)[1]}
                                      </small>
                                    </div>
                                  </small>
                                </div>
                              )}
                              {todayDuty.length > 0 && (
                                <div className="d-flex align-items-center" style={{ gap: 10 }}>
                                  <small className={clsx('text-muted', style.hCap)}>ДЕЖ</small>
                                  {todayDuty.map((d) => {
                                    const [n1, n2] = d.user.name.split(/\s/);
                                    return (
                                      <small
                                        key={d.id}
                                        className="d-flex align-items-center"
                                        style={{ gap: 5 }}
                                      >
                                        <PohAva width={20} src={d.user.photo} alt={d.user.name} />
                                        <div style={{ lineHeight: '0.85em' }}>
                                          <small className="d-block mt-1">{n1}</small>
                                          <small className="d-block text-muted">{n2}</small>
                                        </div>
                                      </small>
                                    );
                                  })}
                                </div>
                              )}
                            </div>
                          </div>
                          <BGU
                            className="my-n2"
                            portion={round(factDayAct.amount, 0)}
                            energy={round(factDayAct.energy, 0)}
                            protein={round(factDayAct.proteins, 0)}
                            fat={round(factDayAct.fats, 0)}
                            carbohydrates={round(factDayAct.carbs, 0)}
                            unit={`${act.name} на человека`}
                          />
                        </header>
                        <table
                          className={clsx(
                            'table table-sm table-bordered',
                            style.table,
                            style.breakPage,
                          )}
                        >
                          <thead>
                            <tr>
                              <th style={{ width: '35%' }}>Блюдо</th>
                              <th style={{ width: '35%' }}>Продукт</th>
                              <th style={{ width: '10%' }} className="text-end">
                                Всего,г
                              </th>
                              <th style={{ width: '10%' }} className="text-end">
                                Порция,г
                              </th>
                              <th style={{ width: '10%' }}>Ответств.</th>
                            </tr>
                          </thead>
                          <tbody>
                            {actFood.map((foo) => {
                              return foo.products.map(({ id, name, amount, ex }, ii) => {
                                const product = products.find((x) => x.id === id);
                                let forcedUser = '—';

                                if (foo?.assigneeUser?.name) {
                                  forcedUser = getShortName(foo?.assigneeUser?.name, 1);
                                }

                                if (product?.forcedUser?.name) {
                                  forcedUser = getShortName(product?.forcedUser?.name, 1);
                                }

                                if (forcedUser !== '—') {
                                  uset.add(forcedUser);
                                }

                                return (
                                  <tr key={`${foo.id}${id}`}>
                                    {ii === 0 && (
                                      <td rowSpan={foo.products.length} valign="top">
                                        <RecipeCookingInfo
                                          className="float-end"
                                          style={{ gap: 6 }}
                                          members_count={hikingData.hikers.length}
                                          cooking_time={foo.cooking_time}
                                          water_count={foo.water_count}
                                          gas_count={foo.gas_count}
                                        />
                                        <b>{foo.name}</b>
                                        {foo?.text?.length > 0 && foo?.text !== foo.name && (
                                          <div
                                            style={{ fontSize: '0.6em', whiteSpace: 'pre-wrap' }}
                                          >
                                            {foo.text}
                                          </div>
                                        )}
                                      </td>
                                    )}
                                    <td className="">
                                      <div className="text-truncate text-nowrap">
                                        {name}{' '}
                                        {ex && (
                                          <small className="text-muted">
                                            {' '}
                                            (ex.{getShortName(ex.name)}
                                            <sup>&times;{ex.rate}</sup>)
                                          </small>
                                        )}
                                      </div>
                                    </td>
                                    <td className="text-end">
                                      {round(amount * foo.correction * hikingData.hikers.length, 0)}
                                    </td>
                                    <td className="text-end">
                                      {round(amount * foo.correction, 0)}
                                    </td>
                                    <td
                                      width={1}
                                      style={
                                        product?.forcedUser || foo?.assigneeUser
                                          ? {
                                              backgroundImage: `url('${product?.forcedUser?.photo || foo.assigneeUser?.photo}')`,
                                              backgroundRepeat: 'no-repeat',
                                              backgroundPosition: '99% 50%',
                                              backgroundSize: '20px',
                                            }
                                          : {}
                                      }
                                    >
                                      {forcedUser}
                                    </td>
                                  </tr>
                                );
                              });
                            })}
                          </tbody>
                          <tfoot>
                            <tr>
                              <th colSpan={2} className="text-end">
                                Итого
                              </th>
                              <th className="text-end">
                                {digitsDivision(
                                  round(factDayAct.amount * hikingData.hikers.length, 0),
                                )}
                                &thinsp;г.
                              </th>
                              <th className="text-end">{round(factDayAct.amount, 0)}</th>
                              <th className="text-end">
                                <small>
                                  <small>{Array.from(uset).join(', ')}</small>
                                </small>
                              </th>
                            </tr>
                          </tfoot>
                        </table>
                        {/* <List */}
                        {/*    flush */}
                        {/*    data={ */}
                        {/*        actFood.map(foo => ({ */}
                        {/*            key: foo.id, */}
                        {/*            className: 'py-2', */}
                        {/*            content: <HikingMenuItem */}
                        {/*                data={foo} */}
                        {/*            /> */}
                        {/*        })) */}
                        {/*    } */}
                        {/* /> */}
                      </PohCol>
                    </PohRow>
                  );
                })}
              </section>
            </div>
          );
        })}
    </PohContainer>
  );
};

export default HikingMenuPrint;
